from __future__ import annotations

from typing import TYPE_CHECKING, Any, Dict, List, Literal, Optional
from urllib.parse import urlparse

from pydantic import BaseModel, ConfigDict, Field, model_validator

from rasa.constants import ENV_SANIC_WORKERS
from rasa.core.constants import DEFAULT_SERVER_PORT
from rasa.exceptions import ValidationError
from rasa.shared.agents.auth.utils import validate_secrets_in_params
from rasa.shared.exceptions import RasaException
from rasa.utils.url_tools import UrlSchema

if TYPE_CHECKING:
    from a2a.types import AgentCard

    from rasa.shared.core.domain import Domain

A2A_SERVER_KEY = "a2a_server"

# Default max wall-clock for one in-flight A2A task before auto-cancel (seconds).
DEFAULT_A2A_TASK_TIMEOUT_SECONDS = 600

# Memory guard: default cap on distinct active
# ``context_id`` sessions (``A2AContextGuard``).
# Limits per-process session bookkeeping when orchestrators open many contexts without
# reaching a terminal task outcome; ``max_contexts: 0`` disables the cap.
DEFAULT_MAX_A2A_CONTEXTS = 1000

_BIND_ALL_INTERFACES = frozenset({"0.0.0.0", "::", "[::]"})


def _public_host_for_agent_card(interface: Optional[str]) -> str:
    """Host name to advertise when the server binds to all interfaces."""
    if interface is None or interface in _BIND_ALL_INTERFACES:
        return "localhost"
    return interface


_SUPPORTED_JWT_ALGORITHMS = frozenset(
    {"HS256", "HS512", "RS256", "RS512", "ES256", "ES512", "PS256"}
)
_SYMMETRIC_JWT_ALGORITHMS = frozenset({"HS256", "HS512"})


class A2AJwtAuthConfig(BaseModel):
    """JWT verification settings for inbound A2A bearer auth."""

    model_config = ConfigDict(extra="forbid")

    algorithm: str = Field(
        default="RS256",
        description=(
            "JWT signing algorithm used by the identity provider. "
            "Supported: HS256, HS512, RS256, RS512, ES256, ES512, PS256."
        ),
    )
    public_key_path: Optional[str] = Field(
        default=None,
        description=(
            "Path to a PEM public key file. Required for asymmetric algorithms "
            "(RS*, ES*, PS*)."
        ),
    )
    secret: Optional[str] = Field(
        default=None,
        description=(
            "Shared secret for symmetric algorithms (HS256, HS512). "
            "Use environment variable interpolation, e.g. '${JWT_SECRET}'."
        ),
    )
    issuer: Optional[str] = Field(
        default=None,
        description="If set, reject tokens whose 'iss' claim does not match.",
    )
    audience: Optional[str] = Field(
        default=None,
        description="If set, reject tokens whose 'aud' claim does not match.",
    )

    @model_validator(mode="after")
    def validate_key_material(self) -> "A2AJwtAuthConfig":
        algorithm = self.algorithm.upper()
        if algorithm not in _SUPPORTED_JWT_ALGORITHMS:
            raise ValueError(
                f"Unsupported JWT algorithm '{self.algorithm}'. "
                f"Supported: {sorted(_SUPPORTED_JWT_ALGORITHMS)}"
            )
        self.algorithm = algorithm

        if algorithm in _SYMMETRIC_JWT_ALGORITHMS:
            if not self.secret:
                raise ValueError(
                    f"JWT algorithm '{algorithm}' requires 'secret' to be configured."
                )
            validate_secrets_in_params(
                {"secret": self.secret},
                "A2A server JWT auth",
                additional_secret_keys=["secret"],
            )
        elif not self.public_key_path:
            raise ValueError(
                f"JWT algorithm '{algorithm}' requires 'public_key_path' "
                "to be configured."
            )
        return self


class A2AAuthConfig(BaseModel):
    """Bearer JWT authentication configuration for the A2A server."""

    model_config = ConfigDict(extra="forbid")

    type: Literal["bearer"]
    jwt: A2AJwtAuthConfig = Field(
        description="JWT verification settings for inbound bearer tokens.",
    )


class A2AServerConfig(BaseModel):
    """Configuration for the A2A protocol on the Rasa Sanic server.

    When an ``a2a_server`` block is present in ``endpoints.yml``, ``rasa run``
    registers A2A JSON-RPC routes on the main server (same port as REST/channels).
    """

    model_config = ConfigDict(extra="forbid")

    url: Optional[str] = Field(
        default=None,
        description=(
            "Public base URL of the Rasa server as seen by A2A orchestrators, "
            "advertised in the AgentCard (scheme, host, port, path prefix). "
            "If omitted at startup, ``rasa run`` builds a URL from --port, "
            "--interface, and ``--ssl-certificate`` / ``--ssl-keyfile`` flags."
        ),
    )
    agent_card_path: Optional[str] = None
    description: str = Field(
        ...,
        min_length=1,
        description=(
            "Required public description for the AgentCard. Used for auto-generated "
            "and placeholder cards. Ignored when 'agent_card_path' points to a static "
            "AgentCard JSON file."
        ),
    )
    include_conversation_repair: bool = True
    task_timeout_seconds: Optional[int] = Field(
        default=None,
        ge=0,
        description=(
            "Maximum seconds each in-flight A2A ``task_id`` may run before the "
            "server auto-cancels that task (safety net; use explicit "
            "``tasks/cancel`` as the primary path). Timers are per task and are "
            "not extended by later ``message/send`` on the same ``context_id``. "
            "When omitted, defaults to "
            f"{DEFAULT_A2A_TASK_TIMEOUT_SECONDS} seconds. Set to ``0`` to "
            "disable."
        ),
    )
    a2a_message_cache_ttl_seconds: Optional[int] = Field(
        default=None,
        ge=0,
        description=(
            "TTL in seconds for ``A2AMessageCache`` entries keyed by "
            "``(context_id, message_id)``. When omitted, defaults to "
            f"{DEFAULT_A2A_TASK_TIMEOUT_SECONDS} seconds (same as task timeout). "
            "Set to ``0`` for immediate expiry (effectively disables replay)."
        ),
    )
    max_contexts: Optional[int] = Field(
        default=None,
        ge=0,
        description=(
            "Memory guard: maximum distinct ``context_id`` sessions retained until "
            "a terminal task outcome. ``input_required`` keeps the session reserved. "
            "When omitted, defaults to "
            f"{DEFAULT_MAX_A2A_CONTEXTS}. Set to ``0`` to disable the cap."
        ),
    )
    push_notifications_enabled: bool = Field(
        default=False,
        description=(
            "When ``true``, the AgentCard advertises push notifications and the "
            "server may POST task updates to orchestrator-supplied callback URLs. "
            "Disabled by default because callback URLs are client-controlled and "
            "can be an SSRF vector when the A2A endpoint is reachable by untrusted "
            "callers. Validation resolves DNS before each POST, but httpx resolves "
            "again at connect time (DNS rebinding TOCTOU); prefer HTTPS callbacks "
            "and restrict hosts with ``push_notification_allowed_hosts`` when "
            "enabling this feature."
        ),
    )
    push_notification_allowed_hosts: Optional[List[str]] = Field(
        default=None,
        description=(
            "Optional hostname allowlist for push callback URLs. When set, only "
            "http(s) URLs whose host matches an entry (exact or subdomain) are "
            "accepted. Loopback and private-network targets are always rejected, "
            "including hostnames that resolve to those addresses. The allowlist "
            "limits which hostnames may be registered but does not alone eliminate "
            "DNS rebinding for allowed domains the orchestrator controls; HTTPS "
            "callbacks reduce rebinding impact, while HTTP callbacks carry higher "
            "SSRF risk."
        ),
    )
    auth: Optional[A2AAuthConfig] = None

    @model_validator(mode="after")
    def validate_push_notification_allowed_hosts(self) -> "A2AServerConfig":
        if self.push_notification_allowed_hosts is None:
            return self
        normalized = [host.strip() for host in self.push_notification_allowed_hosts]
        if not normalized or any(not host for host in normalized):
            raise ValueError(
                "'push_notification_allowed_hosts' must contain at least one "
                "non-empty hostname when set."
            )
        self.push_notification_allowed_hosts = normalized
        return self

    def effective_task_timeout_seconds(self) -> Optional[int]:
        """Resolved per-``task_id`` timeout in seconds, or ``None`` when disabled."""
        if self.task_timeout_seconds == 0:
            return None
        if self.task_timeout_seconds is None:
            return DEFAULT_A2A_TASK_TIMEOUT_SECONDS
        return self.task_timeout_seconds

    def effective_message_cache_ttl_seconds(self) -> int:
        """Resolved ``messageId`` cache TTL in seconds."""
        if self.a2a_message_cache_ttl_seconds is not None:
            return self.a2a_message_cache_ttl_seconds
        return self.effective_task_timeout_seconds() or DEFAULT_A2A_TASK_TIMEOUT_SECONDS

    def effective_max_contexts(self) -> Optional[int]:
        """Resolved active-session cap, or ``None`` when disabled."""
        if self.max_contexts == 0:
            return None
        if self.max_contexts is None:
            return DEFAULT_MAX_A2A_CONTEXTS
        return self.max_contexts

    def bind_scheme(
        self,
        *,
        cli_ssl: bool = False,
        agent_card: "AgentCard | None" = None,
    ) -> str:
        """Resolve ``http`` vs ``https`` for AgentCard URLs.

        Precedence: explicit ``url`` scheme, then CLI SSL flags, then an
        already-resolved AgentCard URL, else ``http``.
        """
        valid_schemes = (UrlSchema.HTTP, UrlSchema.HTTPS)
        if self.url:
            scheme = urlparse(self.url.rstrip("/")).scheme
            if UrlSchema(scheme) in valid_schemes:
                return scheme

        if cli_ssl:
            return UrlSchema.HTTPS.value

        if agent_card is not None and agent_card.url:
            scheme = urlparse(agent_card.url).scheme
            if UrlSchema(scheme) in valid_schemes:
                return scheme

        return UrlSchema.HTTP.value

    def effective_url(
        self,
        *,
        port: Optional[int] = None,
        interface: Optional[str] = None,
        scheme: Optional[str] = None,
    ) -> str:
        """Public base URL advertised in the AgentCard and used by orchestrators.

        When ``url`` is set in ``endpoints.yml``, that value is used as-is.
        Otherwise the URL is derived from the Sanic bind settings passed in by
        ``rasa run`` (``--port``, ``--interface``, SSL certificate flags).
        """
        if self.url:
            return self.url.rstrip("/")
        bind_port = port if port is not None else DEFAULT_SERVER_PORT
        bind_scheme = scheme if scheme is not None else self.bind_scheme()
        bind_host = _public_host_for_agent_card(interface)
        return f"{bind_scheme}://{bind_host}:{bind_port}"

    @classmethod
    def from_dict(cls, data: Optional[Dict[str, Any]]) -> Optional["A2AServerConfig"]:
        if data is None:
            return None
        return cls.model_validate(data)


def validate_a2a_server_domain_session_config_or_raise(
    a2a_server: Optional[A2AServerConfig],
    domain: Optional["Domain"],
) -> None:
    """Ensure domain session settings are compatible with A2A sub-agent mode.

    Resumed A2A contexts reuse the same ``sender_id``. If
    ``start_session_after_expiry`` is enabled, Rasa runs ``action_session_start``
    after inactivity and can reset slot state silently.

    Args:
        a2a_server: Parsed A2A server configuration from ``endpoints.yml``.
        domain: Loaded assistant domain.

    Raises:
        ValidationError: If ``a2a_server`` is configured but session config
        would start a new session on resume.
    """
    if a2a_server is None or domain is None:
        return

    from rasa.shared.core.domain import START_SESSION_AFTER_EXPIRY_KEY

    session_config = domain.session_config
    if session_config.start_session_after_expiry:
        raise ValidationError(
            code="validation.a2a_server.incompatible_session_config",
            event_info=(
                "When the `a2a_server` key is configured in `endpoints.yml`, domain "
                f"`session_config` must set `{START_SESSION_AFTER_EXPIRY_KEY}: false` "
                "so resumed A2A contexts do not trigger `action_session_start` and "
                "reset slots. Example:\n\n"
                "session_config:\n"
                "  session_expiration_time: 60\n"
                f"  {START_SESSION_AFTER_EXPIRY_KEY}: false"
            ),
        )


def validate_a2a_server_sanic_workers_or_raise(
    a2a_server: Optional[A2AServerConfig],
    *,
    number_of_workers: int,
) -> None:
    """Refuse startup when A2A is enabled with multiple Sanic workers.

    Until A2A task and message stores are backed by Redis, idempotency,
    in-flight conflict (HTTP 409), orchestrator cancel, and ``max_contexts``
    are per-worker only. Use ``SANIC_WORKERS=1`` per replica and scale
    horizontally with ingress session affinity until shared stores ship.

    Args:
        a2a_server: Parsed A2A server configuration from ``endpoints.yml``.
        number_of_workers: Resolved Sanic worker count for ``app.run()``.

    Raises:
        ValidationError: If ``a2a_server`` is configured with ``workers > 1``.
    """
    if a2a_server is None or number_of_workers <= 1:
        return

    raise ValidationError(
        code="validation.a2a_server.incompatible_sanic_workers",
        event_info=(
            "When the `a2a_server` key is configured in `endpoints.yml`, Rasa "
            f"must run with `{ENV_SANIC_WORKERS}=1` until Redis-backed A2A task "
            "and message stores are supported. Multiple Sanic workers break "
            "messageId idempotency, in-flight HTTP 409, orchestrator cancel, and "
            "the max_contexts guard. Scale with additional replicas and ingress "
            "session affinity instead."
        ),
    )


def parse_a2a_server_config(
    raw_config: Optional[Dict[str, Any]],
) -> Optional[A2AServerConfig]:
    """Parse and validate ``a2a_server`` configuration from ``endpoints.yml``."""
    if raw_config is None:
        return None
    try:
        return A2AServerConfig.from_dict(raw_config)
    except RasaException:
        raise
    except Exception as exc:
        raise RasaException(
            f"Failed to parse '{A2A_SERVER_KEY}' configuration: {exc}"
        ) from exc
